import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Lua 脚本","description":"","frontmatter":{},"headers":[],"relativePath":"development/lua/index.md","filePath":"development/lua/index.md","lastUpdated":1791683719000}`),a={name:`development/lua/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="lua-脚本" tabindex="-1">Lua 脚本 <a class="header-anchor" href="#lua-脚本" aria-label="Permalink to “Lua 脚本”">​</a></h1><p>Lua 脚本为 Xray 提供灵活的扩展方式，可用于实现自定义功能，与核心交互。</p><h2 id="入门" tabindex="-1">入门 <a class="header-anchor" href="#入门" aria-label="Permalink to “入门”">​</a></h2><p>先阅读<a href="./environment.html">运行环境与脚本加载</a>，了解 Lua 支持范围、模块加载方式和脚本文件定位规则。</p><h2 id="编写指南" tabindex="-1">编写指南 <a class="header-anchor" href="#编写指南" aria-label="Permalink to “编写指南”">​</a></h2><p>根据需要实现的功能选择指南，从最小示例开始，逐步编写自己的脚本：</p><table tabindex="0"><thead><tr><th>指南</th><th>作用</th><th>内容</th></tr></thead><tbody><tr><td><a href="./guide/routing.html">路由脚本</a></td><td>自定义路由规则</td><td>出站选择、负载均衡、主动解析后按 IP 分流</td></tr><tr><td><a href="./guide/dns.html">DNS 脚本</a></td><td>自定义 DNS 查询规则</td><td>上游选择、查询回退、结果过滤</td></tr></tbody></table><p>当前的路由和 DNS 脚本都使用池化实例。编写脚本时，请结合<a href="./guide/lifecycle.html#池化生命周期">池化生命周期</a>理解顶层初始化和状态保留。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to “参考”">​</a></h2><h3 id="hook" tabindex="-1">Hook <a class="header-anchor" href="#hook" aria-label="Permalink to “Hook”">​</a></h3><p>Hook 是脚本中供核心在特定时机调用的 Lua 函数。脚本入口决定可用的 Hook 及其调用约定，一个入口可以对应多个 Hook。具体需要实现哪些 Hook，以相应入口的说明为准。</p><p>目前支持的入口和 Hook 如下，参数、返回值和失败行为见各 Hook 的参考页：</p><table tabindex="0"><thead><tr><th>脚本入口</th><th>Hook</th></tr></thead><tbody><tr><td><code>routing.script</code></td><td><a href="./reference/hook-routing.html">HandleRoute</a></td></tr><tr><td><code>dns.script</code></td><td><a href="./reference/hook-dns.html">HandleDNSQuery</a></td></tr></tbody></table><h3 id="数据类型" tabindex="-1">数据类型 <a class="header-anchor" href="#数据类型" aria-label="Permalink to “数据类型”">​</a></h3><p>除 Lua 自带的数据类型外，Xray Lua 还使用 <code>net.IP</code>、Go slice 和 <code>error</code> 等类型，其在 Lua 中的表示与操作方式见<a href="./reference/data-types.html">数据类型</a>。</p><h3 id="模块-api" tabindex="-1">模块 API <a class="header-anchor" href="#模块-api" aria-label="Permalink to “模块 API”">​</a></h3><p>按功能查阅模块 API：</p><table tabindex="0"><thead><tr><th>模块</th><th>用途</th></tr></thead><tbody><tr><td><a href="./reference/module-router.html">xray.router</a></td><td>策略路由</td></tr><tr><td><a href="./reference/module-dns.html">xray.dns</a></td><td>域名解析</td></tr><tr><td><a href="./reference/module-geodata.html">xray.geodata</a></td><td>域名和 IP 匹配、过滤</td></tr><tr><td><a href="./reference/module-log.html">xray.log</a></td><td>输出日志</td></tr></tbody></table>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};